{"source":"def audit(events, at):
    eligible = [event for event in events if event["seen"] <= at]
    selected = {}
    fences = {}
    for event in eligible:
        key = event["key"]
        selected.setdefault(key, {})
        if event["kind"] == "fence":
            pair = (key, event["side"])
            fences[pair] = max(fences.get(pair, 0), event["through"])
    for event in eligible:
        if event["kind"] != "ack":
            continue
        key = event["key"]
        side = event["side"]
        epoch = event["epoch"]
        if epoch <= fences.get((key, side), 0):
            continue
        sides = selected[key]
        previous = sides.get(side)
        if previous is None or epoch > previous[0]:
            sides[side] = (epoch, {event["digest"]})
        elif epoch == previous[0]:
            previous[1].add(event["digest"])
    result = {}
    for key, sides in selected.items():
        left = sides.get("L")
        right = sides.get("R")
        if not sides:
            result[key] = "withdrawn"
        elif any(len(value[1]) > 1 for value in sides.values()):
            result[key] = "conflict"
        elif left is None or right is None or left[0] != right[0]:
            result[key] = "pending"
        elif left[1] != right[1]:
            result[key] = "diverged"
        else:
            result[key] = "verified"
    return result
